// A data é lida no fuso de Brasília: rodando em UTC, depois das 21h o servidor
// já está no dia seguinte e o aviso do dia da eleição chegaria atrasado.
const hoje = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });

const AGENDA = {
  '2026-10-01': { nivel: 'aviso', texto: 'Faltam 3 dias. Confira no DivulgaCand se os registros 15115 e 2223 continuam deferidos — o site afirma que estão.' },
  '2026-10-02': { nivel: 'aviso', texto: 'Véspera da véspera. Combine com a Vilma o que fica publicado no domingo e quem tem o celular na mão.' },
  '2026-10-03': { nivel: 'aviso', texto: 'VÉSPERA. A partir de amanhã NÃO se publica conteúdo novo no site nem nas redes: publicação nova no dia da eleição é CRIME (Lei 9.504/97, art. 39, §5º, III e IV). Deixe a agenda e o formulário do jeito que devem passar o domingo.' },
  '2026-10-04': { nivel: 'erro',  texto: 'HOJE É O DIA DA ELEIÇÃO. Ninguém publica nada: nem post, nem evento na agenda, nem troca de texto no painel. Publicação nova hoje é crime, não multa. Se precisar TIRAR alguma coisa do ar, pode — tirar não é publicar.' },
  '2026-10-05': { nivel: 'info',  texto: 'Eleição passou. Dá para voltar a publicar. Antes de qualquer coisa, converse com a Vilma sobre o que o site vira agora.' },
};

const a = AGENDA[hoje];
if (!a) return [];   // dia comum: o fluxo termina sem mandar nada
return [{ json: { data: hoje, ...a,
  assunto: `[Vilma] ${a.nivel === 'erro' ? 'ATENÇÃO — ' : ''}${hoje}` } }];
